-- LOCAL ONLY. Read capabilities, no monthly validation writer or payment.
BEGIN;SET LOCAL lock_timeout='10s';SET LOCAL search_path=pg_catalog;LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;SELECT pg_advisory_xact_lock(61001,1);LOCK TABLE public.folha_registos,public.folha_historico,public.folha_gestao_historico,public.folha_avaliacoes_diarias,public.folha_jornadas_individuais_versoes,public.folha_config_empresa,public.quadro_equipa_permanencias,public.ausencias,public.folha_vencimentos,public.ponto_pessoal_obra,folha_privado.operacoes IN SHARE ROW EXCLUSIVE MODE;
DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $base$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_faltou_v2(text,jsonb,boolean,text)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='v' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='094dc4ab55da2be8d497dc8d7b99f6fc15b24e76ca81e014c6f244d17425fe6e' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_faltou_v2(text,jsonb,boolean,text)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_gestao_v2(text,jsonb,boolean,text)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='v' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='97b41cd118aa9efee1fb960bf2d9d39585b3e4e7f525c624372e13adf374c856' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_gestao_v2(text,jsonb,boolean,text)';END IF;
END $base$;
DO $absent$ BEGIN IF to_regprocedure('public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)') IS NOT NULL OR to_regprocedure('public.fn_folha_conferencia_contexto_v3(uuid,date)') IS NOT NULL OR to_regprocedure('public.fn_folha_horas_contexto_v3(date,uuid)') IS NOT NULL THEN RAISE EXCEPTION 'HORAS_READ_PRESENT_OR_PARTIAL';END IF;END $absent$;
DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_horas_leituras_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_horas_leituras_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_horas_leituras_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_horas_leituras_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'HORAS_READ_BACKUP_NOT_PRIVATE';END IF;
FOR r IN SELECT * FROM primeline_horas_leituras_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'HORAS_READ_DATA_DRIFT';END IF;END LOOP;END $data$;
-- Local readers only. They confer nothing, generate no payment and do not invent expected hours.
CREATE FUNCTION public.fn_folha_relatorio_horas_v3(p_obra_id uuid,p_inicio date,p_fim date,p_kind text DEFAULT NULL,p_fornecedor_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $report$
DECLARE u public.utilizadores;records jsonb;legacy jsonb;days jsonb;weeks jsonb;months jsonb;
BEGIN
 u:=folha_privado.ator();IF p_obra_id IS NULL OR p_inicio IS NULL OR p_fim IS NULL OR p_fim<p_inicio OR p_fim-p_inicio>30 OR p_kind IS NOT NULL AND p_kind NOT IN('primeline','external') THEN RAISE EXCEPTION 'REPORT_RANGE_INVALID: até 31 dias';END IF;
 PERFORM folha_privado.obra(p_obra_id);
 IF p_fornecedor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fornecedores WHERE id=p_fornecedor_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: fornecedor' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'revision',f.revision,'date',f.data,'work_id',f.obra_id,'person_id',coalesce(f.colaborador_id,f.externo_id),'kind',CASE WHEN f.externo_id IS NULL THEN 'primeline' ELSE 'external' END,'name',coalesce(c.nome,e.nome),'provider_id',e.fornecedor_id,'provider_name',provider.nome,'intervals',f.intervals,'minutes',f.minutes,'open',f.estado='open','corrected',EXISTS(SELECT 1 FROM public.folha_historico h WHERE h.empresa_id=u.empresa_id AND h.person_id=coalesce(f.colaborador_id,f.externo_id) AND h.kind=CASE WHEN f.externo_id IS NULL THEN 'primeline' ELSE 'external' END AND h.obra_id=f.obra_id AND h.data=f.data AND h.antes IS NOT NULL AND h.antes<>'null'::jsonb),'last_changed_at',f.atualizado_em,'changed_by',f.atualizado_por) ORDER BY f.data,f.id),'[]') INTO records
 FROM public.folha_registos f LEFT JOIN public.colaboradores c ON c.id=f.colaborador_id AND c.empresa_id=u.empresa_id LEFT JOIN public.folha_externos e ON e.id=f.externo_id AND e.empresa_id=u.empresa_id LEFT JOIN public.fornecedores provider ON provider.id=e.fornecedor_id AND provider.empresa_id=u.empresa_id
 WHERE f.empresa_id=u.empresa_id AND f.obra_id=p_obra_id AND f.data BETWEEN p_inicio AND p_fim AND (p_kind IS NULL OR p_kind='primeline' AND f.colaborador_id IS NOT NULL OR p_kind='external' AND f.externo_id IS NOT NULL) AND (p_fornecedor_id IS NULL OR e.fornecedor_id=p_fornecedor_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object('source','legacy','original',to_jsonb(p)) ORDER BY p.data,p.id),'[]') INTO legacy FROM public.ponto_pessoal_obra p WHERE p.empresa_id=u.empresa_id AND p.obra_id=p_obra_id AND p.data BETWEEN p_inicio AND p_fim AND p_kind IS DISTINCT FROM 'external' AND p_fornecedor_id IS NULL;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.date,x.person_id),'[]') INTO days FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,r->>'date' date,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',r->>'date') x;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.week,x.person_id),'[]') INTO weeks FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,date_trunc('week',(r->>'date')::date)::date week,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',date_trunc('week',(r->>'date')::date)::date) x;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.month_start,x.person_id),'[]') INTO months FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,date_trunc('month',(r->>'date')::date)::date month_start,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',date_trunc('month',(r->>'date')::date)::date) x;
 RETURN jsonb_build_object('version',3,'committed',false,'work_id',p_obra_id,'from',p_inicio,'to',p_fim,'records',records,'daily',days,'weekly',weeks,'monthly',months,'legacy',legacy,'legacy_included_in_totals',false,'financial_effect',false,'classification_included',false);
END $report$;
CREATE FUNCTION public.fn_folha_conferencia_contexto_v3(p_colaborador_id uuid,p_competencia date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $monthly$
DECLARE u public.utilizadores;facts jsonb;records jsonb;evals jsonb;
BEGIN
 u:=folha_privado.ator();IF NOT folha_privado.admin() OR NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=p_colaborador_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: conferência interna' USING ERRCODE='42501';END IF;
 IF p_competencia IS NULL OR extract(day FROM p_competencia)<>1 THEN RAISE EXCEPTION 'MONTH_REQUIRED';END IF;
 facts:=folha_privado.payroll_facts(p_colaborador_id,p_competencia);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'revision',f.revision,'date',f.data,'work_id',f.obra_id,'intervals',f.intervals,'minutes',f.minutes,'state',f.estado,'changed_by',f.atualizado_por,'changed_at',f.atualizado_em) ORDER BY f.data,f.id),'[]') INTO records FROM public.folha_registos f WHERE f.empresa_id=u.empresa_id AND f.colaborador_id=p_colaborador_id AND f.data>=p_competencia AND f.data<(p_competencia+interval '1 month')::date;
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.data,a.id),'[]') INTO evals FROM public.folha_avaliacoes_diarias a WHERE a.empresa_id=u.empresa_id AND a.colaborador_id=p_colaborador_id AND a.data>=p_competencia AND a.data<(p_competencia+interval '1 month')::date;
 RETURN jsonb_build_object('version',3,'committed',false,'person_id',p_colaborador_id,'month',p_competencia,'records',records,'evaluations',evals,'facts',facts,'he_policy','HR-27','financial_effect',false,'conference_write_capability',false,'expected_monthly_minutes',NULL,'expected_coverage_state','requires_daily_reference_coverage');
END $monthly$;
CREATE FUNCTION public.fn_folha_horas_contexto_v3(p_data date,p_obra_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $context$
DECLARE u public.utilizadores;c jsonb;row_data jsonb;rows jsonb:='[]';j public.folha_jornadas_individuais_versoes;cut date;
BEGIN
 u:=folha_privado.ator();c:=public.fn_folha_contexto_v2(p_data,p_obra_id);SELECT avaliacao_diaria_data_ativacao INTO cut FROM public.folha_config_empresa WHERE empresa_id=u.empresa_id;
 FOR row_data IN SELECT value FROM jsonb_array_elements(c->'rows') LOOP
  j:=NULL;IF cut IS NOT NULL AND p_data>=cut THEN SELECT * INTO j FROM public.folha_jornadas_individuais_versoes WHERE empresa_id=u.empresa_id AND colaborador_id=(row_data->>'person_id')::uuid AND vigente_desde<=p_data AND (vigente_ate IS NULL OR vigente_ate>p_data);END IF;
  rows:=rows||jsonb_build_array(row_data||jsonb_build_object('individual_reference',CASE WHEN j.id IS NULL THEN NULL ELSE jsonb_build_object('confirmed',true,'source','individual','version_id',j.id,'revision',j.revision,'effective_from',j.vigente_desde,'effective_to',j.vigente_ate,'week',j.semana) END));
 END LOOP;
 RETURN c||jsonb_build_object('version',3,'rows',rows,'he_policy','HR-27','reference_edit_capability',false,'operational_write_capabilities',jsonb_build_object('existing_periods_save',true,'neutral_faltou',true,'free_destinations',false,'normal_individual_evaluation',false));
END $context$;
REVOKE ALL ON FUNCTION public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid),public.fn_folha_conferencia_contexto_v3(uuid,date),public.fn_folha_horas_contexto_v3(date,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid),public.fn_folha_conferencia_contexto_v3(uuid,date),public.fn_folha_horas_contexto_v3(date,uuid) TO authenticated;
DO $installed$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='s' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b185fb111d185f19fceb2f0f2ffac1d473ae5b324a9a589b815304cd096f3b9d' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_contexto_v3(uuid,date)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='s' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='3c66b79ac1882a756ccd430fa403e5c4c195c195e8ddb77ae7699dc80b78ee6c' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_conferencia_contexto_v3(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_horas_contexto_v3(date,uuid)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='s' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='4162758ceba25fab4a3610746de8c92f8fb5548f9970d8a06997b3f8d0ca8f1b' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_horas_contexto_v3(date,uuid)';END IF;
END $installed$;
DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_horas_leituras_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_horas_leituras_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_horas_leituras_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_horas_leituras_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'HORAS_READ_BACKUP_NOT_PRIVATE';END IF;
FOR r IN SELECT * FROM primeline_horas_leituras_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'HORAS_READ_DATA_DRIFT';END IF;END LOOP;END $data$;
SELECT 'HORAS_READ_INSTALLED' resultado;COMMIT;
